  const sec = document.querySelector\('section'\);
  const imgs = [...sec.querySelectorAll\('img'\)].map\(i => { const r = i.getBoundingClientRect\(\); return { src: i.src.split\('url='\)[1]?.split\('&'\)[0], x: Math.round\(r.x\), y: Math.round\(r.y\), w: Math.round\(r.width\), h: Math.round\(r.height\) }; }\);
  const btn = [...sec.querySelectorAll\('a'\)].find\(a => a.textContent.includes\('Pre-order your'\)\);
  const b = btn.getBoundingClientRect\(\);
  const cx = b.x + b.width / 2, cy = b.y + b.height / 2;
  const top = document.elementFromPoint\(cx, cy\);
  const grid = getComputedStyle\(sec\).gridTemplateColumns;
  return { imgs, btn: { x: Math.round\(b.x\), y: Math.round\(b.y\), w: Math.round\(b.width\), h: Math.round\(b.height\) }, topAtBtnCenter: top.tagName + '.' + \(top.className || ''\).toString\(\).slice\(0, 40\), grid, secH: Math.round\(sec.getBoundingClientRect\(\).height\) };
}\)\(\)`\);
console.log\(JSON.stringify\(info, null, 1\)\);
c.close\(\);
EOF
