const dims = await c.evl\(`\({w: document.documentElement.scrollWidth, h: document.documentElement.scrollHeight}\)`\);
console.log\("full dims:", JSON.stringify\(dims\), "errors:", c.errors.length ? c.errors : "none"\);
c.close\(\);
EOF
